import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"12.4 心肺复苏与急救方法","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-4-xin-fei-fu-su-yu-ji-jiu-fang-fa.md","filePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-4-xin-fei-fu-su-yu-ji-jiu-fang-fa.md","lastUpdated":1793096070000}'),e={name:"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-4-xin-fei-fu-su-yu-ji-jiu-fang-fa.md"};function r(n,t,s,d,h,u){return i(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="_12-4-心肺复苏与急救方法" tabindex="-1">12.4 心肺复苏与急救方法 <a class="header-anchor" href="#_12-4-心肺复苏与急救方法" aria-label="Permalink to &quot;12.4 心肺复苏与急救方法&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>当触电者心跳、呼吸停止,分秒必争。心肺复苏(CPR)是把&quot;心跳和呼吸&quot;抢回来的技术:胸外按压 + 人工呼吸。这一节掌握操作要点(位置、深度、频率、比例),实操考核必考。</p><h2 id="一、心肺复苏前要先判断" tabindex="-1">一、心肺复苏前要先判断 <a class="header-anchor" href="#一、心肺复苏前要先判断" aria-label="Permalink to &quot;一、心肺复苏前要先判断&quot;">​</a></h2><p>触电者脱离电源后,先判断:</p><ol><li><strong>拍肩呼喊</strong>:判断有无意识;</li><li><strong>看胸腹起伏</strong>:判断有无呼吸;</li><li><strong>摸颈动脉</strong>:判断有无心跳;</li></ol><p>若<strong>无意识、无呼吸、无心跳</strong>——立即呼叫 120,并<strong>就地</strong>开始心肺复苏。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无意识 + 无呼吸 + 无心跳 ──► 立即CPR + 呼救120</span></span></code></pre></div><h2 id="二、心肺复苏两大操作" tabindex="-1">二、心肺复苏两大操作 <a class="header-anchor" href="#二、心肺复苏两大操作" aria-label="Permalink to &quot;二、心肺复苏两大操作&quot;">​</a></h2><h3 id="_1-胸外按压-压心脏" tabindex="-1">1. 胸外按压(压心脏) <a class="header-anchor" href="#_1-胸外按压-压心脏" aria-label="Permalink to &quot;1. 胸外按压(压心脏)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要点</th><th>标准</th></tr></thead><tbody><tr><td><strong>按压位置</strong></td><td>两乳头连线的中点(胸骨下 1/2,剑突上)</td></tr><tr><td><strong>按压深度</strong></td><td>成人 <strong>5~6 厘米</strong></td></tr><tr><td><strong>按压频率</strong></td><td>成人 <strong>100~120 次/分</strong></td></tr><tr><td><strong>按压姿势</strong></td><td>双手交叉、掌根着力、手臂垂直,用<strong>上半身重量</strong>下压</td></tr><tr><td>注意</td><td>按压后让胸廓<strong>充分回弹</strong>,按压节奏均匀</td></tr></tbody></table><h3 id="_2-人工呼吸-吹气" tabindex="-1">2. 人工呼吸(吹气) <a class="header-anchor" href="#_2-人工呼吸-吹气" aria-label="Permalink to &quot;2. 人工呼吸(吹气)&quot;">​</a></h3><ul><li><strong>开放气道</strong>:仰头抬颏,清除口中异物;</li><li><strong>捏住鼻子</strong>,口对口吹气,每次约 1 秒,看到胸廓<strong>鼓起</strong>;</li><li>每轮吹气 2 次。</li></ul><h2 id="三、按压与吹气的比例-必背" tabindex="-1">三、按压与吹气的比例(必背) <a class="header-anchor" href="#三、按压与吹气的比例-必背" aria-label="Permalink to &quot;三、按压与吹气的比例(必背)&quot;">​</a></h2><p><strong>按压 30 次,吹气 2 次</strong>(30 : 2),为一轮;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按压30次 ──► 吹气2次 ──► 按压30次 ──► 吹气2次 ──► 循环</span></span></code></pre></div><ul><li>持续进行,直到专业救护人员到达或触电者恢复;</li><li>换人操作时尽量减少中断。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>成人心肺复苏按压:吹气比例是 30:2</strong>;按压频率 100~120 次/分。</p></blockquote><h2 id="四、急救中的注意事项" tabindex="-1">四、急救中的注意事项 <a class="header-anchor" href="#四、急救中的注意事项" aria-label="Permalink to &quot;四、急救中的注意事项&quot;">​</a></h2><ul><li><strong>就地抢救</strong>,不要随意搬动触电者(除非有危险);</li><li>抢救前解开衣领、腰带,保持呼吸道通畅;</li><li>不要轻易放弃,<strong>坚持到救护车到达</strong>;</li><li>同时拨打 <strong>120</strong> 求救,请专业人员。</li></ul><blockquote><p>💡 记住:&quot;时间就是生命,坚持就是希望&quot;——电击后停止呼吸心跳,立即心肺复苏能大大提高存活率。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 判断:无意识、无呼吸、无心跳 → 立即 CPR。</li><li>✅ 按压位置:两乳头连线中点;深度 5~6 cm;频率 100~120 次/分。</li><li>✅ 比例:<strong>30 按压 : 2 吹气</strong>。</li><li>✅ 开放气道、捏鼻吹气,坚持到专业救护人员到场。</li><li>⚠️ 易混点:按压部位不能偏(偏上会压断肋骨伤内脏),深度频率不能敷衍。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>心肺复苏 = 胸外按压(压心脏)+ 人工呼吸(通气)。</li><li>按压 30 次、吹气 2 次循环,位置深度频率都要对。</li><li>就地、坚持、边抢救边呼救 120。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)成人心肺复苏胸外按压的频率应为()。 A. 60~80 次/分　B. 100~120 次/分　C. 150~200 次/分　D. 越快越好</li><li>(单选)胸外按压的位置是()。 A. 左胸心脏位置　B. 两乳头连线中点(胸骨下段)　C. 剑突　D. 腹部</li><li>(判断)心肺复苏时,胸外按压与人工呼吸的比例是 30:2。( )</li><li>(判断)人工呼吸前应先开放气道(仰头抬颏),并清除口中异物。( )</li><li>(判断)触电者心跳呼吸停止后,抢救应持续进行,不能轻易放弃。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。成人按压频率 100~120 次/分。</li><li><strong>B</strong>。按压位置在两乳头连线中点(胸骨下段)。</li><li><strong>√</strong>。30 次按压 + 2 次吹气。</li><li><strong>√</strong>。开放气道是吹气的前提。</li><li><strong>√</strong>。坚持抢救到专业人员到场。</li></ol></details>',28)])])}const p=a(e,[["render",r]]);export{c as __pageData,p as default};
